private val cyrillicLetter=Regex("[А-Яа-яЁё]")
private val cyrillicRun=Regex("[А-Яа-яЁё][А-Яа-яЁё /-]*[А-Яа-яЁё]|[А-Яа-яЁё]")
private val fragmentCache=java.util.concurrent.ConcurrentHashMap<String,String>()
/**
 * A text put together from words and numbers ("Найдено 12. Показаны первые 60.") has no dictionary entry of its own. It is
 * translated word group by word group, and only when every Russian group in it is a known interface text — so a name or a
 * note the person typed is left exactly as typed.
 */
internal fun fragmentTranslation(text:String,language:String,exact:(String)->String?):String? {
    if(language=="ru" || text.length>400 || !cyrillicLetter.containsMatchIn(text))return null
    val key=language+"\u0000"+text
    fragmentCache[key]?.let {return it.ifEmpty {null}}
    var known=true
    val result=cyrillicRun.replace(text) {match->exact(match.value.trim()) ?: run {known=false;match.value}}
    val value=if(known && result!=text)result else null
    if(fragmentCache.size>4000)fragmentCache.clear()
    fragmentCache[key]=value ?: ""
    return value
}
